
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hse06_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hse06", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.298979702486714e+00, -3.236966690621333e+00, -3.150166035836867e+00, -3.030125817139735e+00, -2.866980864827115e+00, -2.650742177461372e+00, -2.374221932155183e+00, -2.037760606301507e+00, -1.652747694658554e+00, -1.240247206442678e+00, -8.441761672563844e-01, -5.839636185415980e-01, -5.114544508287258e-01, -4.229108839101020e-01, -3.099827961309104e-01, -2.004409576615578e-01, -1.143270581925288e-01, -4.785633971966678e-02, -1.081067593727720e-02, -1.216203592104553e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


